const{chromium}=require('playwright');const base='http://127.0.0.1:8787';async function api(r,m,p,d){const s=await r.fetch(base+p,{method:m,headers:d===undefined?undefined:{'Content-Type':'application/json'},data:d});const j=await s.json();if(s.status()<200||s.status()>299)throw new Error(j.message||String(s.status()));return j}(async()=>{const b=await chromium.launch({headless:true}),c=await b.newContext({viewport:{width:1440,height:900}});try{const pw='Direct-Opener-2026!',s=await c.request.post(base+'/api/auth/signup',{data:{username:'direct_opener',displayName:'Direct Opener',email:'direct-opener@example.test',password:pw,rememberMe:false}});if(s.status()!==201)throw new Error('signup');const o=await api(c.request,'GET','/api/onboarding'),r=o.relationshipOptions||o.relationships||o.options?.relationships||[],i=o.intentionOptions||o.intentions||o.options?.intentions||[];await api(c.request,'POST','/api/onboarding/relationship',{relationshipId:r[0].id});await api(c.request,'POST','/api/onboarding/intentions',{intentionIds:i.slice(0,2).map(x=>x.id)});await api(c.request,'POST','/api/bootstrap/owner',{password:pw});const p=await c.newPage();const errors=[];p.on('pageerror',e=>errors.push(e.message));await p.goto(base+'/dashboard',{waitUntil:'networkidle'});await p.locator('#customize-dashboard').click();await p.locator('#dashboard-editor-toolbar').waitFor({state:'visible'});await p.locator('#dashboard-advanced-tools').waitFor({state:'visible'});const state=await p.evaluate(()=>({editing:dashboardState.editing,toolbarHidden:document.querySelector('#dashboard-editor-toolbar').hidden,buttonHidden:document.querySelector('#customize-dashboard').hidden,advanced:Boolean(document.querySelector('#dashboard-advanced-tools'))}));if(!state.editing||state.toolbarHidden||!state.buttonHidden||!state.advanced)throw new Error('invalid editor state '+JSON.stringify(state));if(errors.length)throw new Error(errors.join(' | '));await p.locator('#dashboard-cancel-layout').click();console.log('DIRECT DASHBOARD OPENER=PASS '+JSON.stringify(state));}finally{await c.close();await b.close()}})().catch(e=>{console.error('DIRECT DASHBOARD OPENER=FAIL '+(e.stack||e));process.exit(1)});
